mapper.select:
SELECT 
FROM auth_federated_provider
WHERE deleted = 0
AND code = #{code}
AND status = #{status}
AND login_page_visible = #{loginPageVisible}
ORDER BY display_order, id

mapper.update:
UPDATE auth_federated_provider
login_page_visible = #{loginPageVisible.value}, display_order = #{displayOrder.value}, unlinked_identity_action = #{unlinkedIdentityAction.value}, auto_link_verified_email = #{autoLinkVerifiedEmail.value}, i18n = CAST(#{i18n.value} AS JSONB), icon_reference = #{iconReference.value}, icon_reference = NULL, status = #{status.value}, version = version + 1
WHERE code = #{code} AND deleted = 0 AND version = #{expectedVersion}

UPDATE auth_federated_provider
SET version = version + 1
WHERE id = #{providerId} AND deleted = 0 AND version = #{expectedVersion}
